"""The public question set, generated by code from U.S. federal series.

Two parts, kept apart:

- **live**: open questions with deadlines 30 and 90 days after the day they are
  made. Nothing about the answer is published on that day. This part measures
  forecasting.
- **resolved_history**: the same kinds of question made on past dates, with
  their outcomes. **It is not a test of forecasting for any model trained after
  the outcome**, because such a model has read what happened. It exists to test
  the plumbing (formats, resolver, scorers, adapters) and as a template for an
  organization's own private calls.

Every question is one of four kinds, made from the series' own history up to
the question's cutoff (no look-ahead):

- *direction*: will the reading be above the latest one?
- *threshold*: will it be above (or below) a round number near the upper (or
  lower) quartile of historical moves over the same distance?
- *range*: will it land between the rounded lower and upper quartiles?
- *number*: what will it be?
"""

from __future__ import annotations

import hashlib
import math
from collections.abc import Iterable, Sequence
from dataclasses import dataclass, field, replace
from datetime import date, timedelta

from .baselines import History, anchor_at, history
from .calls import Call, Rule, Transform
from .resolve import shift
from .series import Series, SeriesInfo

HORIZONS = (30, 90)
KINDS_MADE = ("direction", "threshold", "range", "number")
MONTHS = ("January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December")


@dataclass(frozen=True)
class Spec:
    """How questions are worded and built for one series."""

    id: str
    noun: str
    period: str
    publish_lag_days: int
    step: float
    decimals: int
    source: str
    agency_series: str
    transform: Transform = field(default_factory=Transform)
    prefix: str = ""
    suffix: str = ""
    grace_extra_days: int = 45

    def fmt(self, v: float) -> str:
        s = f"{abs(v):,.{self.decimals}f}"
        sign = "-" if v < 0 and round(abs(v), self.decimals) != 0 else ""
        return f"{sign}{self.prefix}{s}{self.suffix}"

    def rule(self, **kw: object) -> Rule:
        return Rule(
            period=self.period,
            grace_days=self.publish_lag_days + self.grace_extra_days,
            transform=self.transform,
            **kw,  # type: ignore[arg-type]
        )


