SPEC_BY_ID = {s.id: s for s in SPECS}


def nice(x: float, step: float) -> float:
    """Round to the nearest multiple of ``step`` (and tidy float noise)."""
    r = round(x / step) * step
    return round(r, 6)


def period_label(d: date, period: str) -> str:
    if period == "M":
        return f"{MONTHS[d.month - 1]} {d.year}"
    if period == "Q":
        return f"Q{(d.month - 1) // 3 + 1} {d.year}"
    if period == "A":
        return str(d.year)
    if period == "W":
        return f"the week dated {d.isoformat()}"
    return d.isoformat()


def expected_target(anchor_ts: date, deadline: date, period: str) -> date:
    """The period date a ``last_on_or_before`` rule will pick if every reading arrives."""
    t = anchor_ts
    while True:
        n = shift(t, 1, period)
        if n > deadline:
            return t
        t = n


def target_phrase(spec: Spec, deadline: date, target: date) -> str:
    if spec.period in ("M", "Q", "A"):
        word = {"M": "monthly", "Q": "quarterly", "A": "annual"}[spec.period]
        return f"{period_label(target, spec.period)} (the latest {word} reading dated on or before {deadline.isoformat()})"
    if spec.period == "W":
        return f"the latest weekly reading dated on or before {deadline.isoformat()} (expected: {target.isoformat()})"
    return f"{deadline.isoformat()} (or the last business day before it with a published reading)"


def _qid(made_on: date, spec: Spec, h: int, kind: str) -> str:
    return f"oe-{made_on.isoformat()}-{spec.id}-{h}d-{kind}"


def _flip(made_on: date, spec: Spec, h: int) -> bool:
    """Deterministic coin: threshold questions alternate between 'above' and 'below'."""
    return hashlib.sha256(f"{made_on}{spec.id}{h}".encode()).digest()[0] % 2 == 1


def questions_for(
    spec: Spec,
    series: Series,
    made_on: date,
    split: str,
    horizons: Sequence[int] = HORIZONS,
    cutoff: date | None = None,
) -> list[Call]:
    """The questions for one series on one date. ``cutoff`` defaults to the last reading published by ``made_on``."""
    info = series.info
    if cutoff is None:
        bound = made_on - timedelta(days=spec.publish_lag_days)
        last = series.last_on_or_before(bound)
        if last is None:
            return []
        cutoff = last[0]
    base_rule = spec.rule()
    anc = anchor_at(series, cutoff, base_rule)
    if anc is None:
        return []
    source = info.attribution or info.publisher or spec.source
    license_ = info.license or "U.S. Government work (public domain)"
    out: list[Call] = []
    for h in horizons:
        deadline = made_on + timedelta(days=h)
        hist: History | None = history(series, cutoff, deadline, base_rule)
        if hist is None or hist.n < 24:
            continue
        target = expected_target(anc.timestamp, deadline, spec.period)
        tp = target_phrase(spec, deadline, target)
        a_lab = period_label(anc.timestamp, spec.period)
        common = dict(
            made_on=made_on, deadline=deadline, series_id=spec.id, source=source, license=license_,
            unit=info.unit or None, split=split, cutoff=cutoff, anchor=anc,
            base_change=round(hist.base_change() or 0.0, 9), scale=hist.scale(),
            tags=(spec.source, f"{h}d", spec.period),
        )
        made: list[Call] = []
        # direction
        shown = round(anc.value, spec.decimals)
        r = spec.rule(comparator=">", threshold=shown, threshold_basis=f"the latest reading as of {made_on.isoformat()} ({a_lab}), rounded as shown")
        made.append(Call(
            id=_qid(made_on, spec, h, "direction"), kind="binary", rule=r,
            question=f"Will {spec.noun} for {tp} be above {spec.fmt(shown)}, its value for {a_lab}?",
            base_rate=hist.base_rate(r), **common,  # type: ignore[arg-type]
        ))
        # threshold
        above = not _flip(made_on, spec, h)
        q = hist.quantile(0.75 if above else 0.25)
        thr = nice(anc.value + q, spec.step)
        if math.isclose(thr, nice(anc.value, spec.step)):
            thr = nice(anc.value, spec.step) + (spec.step if above else -spec.step)
        thr = round(thr, 6)
        r = spec.rule(comparator=">" if above else "<", threshold=thr, threshold_basis="a round number near the " + ("upper" if above else "lower") + " quartile of historical moves over the same distance")
        made.append(Call(
            id=_qid(made_on, spec, h, "threshold"), kind="binary", rule=r,
            question=f"Will {spec.noun} for {tp} be {'above' if above else 'below'} {spec.fmt(thr)}?",
            base_rate=hist.base_rate(r), **common,  # type: ignore[arg-type]
        ))
        # range
        # a band from the rounded lower to upper quartile of moves, always containing "no change"
        mid = nice(anc.value, spec.step)
        lo = min(nice(anc.value + hist.quantile(0.25), spec.step), mid)
        hi = nice(anc.value + hist.quantile(0.75), spec.step)
        if hi <= anc.value:
            hi = round(mid + spec.step, 6) if mid <= anc.value else mid
        if lo > anc.value:
            lo = round(mid - spec.step, 6)
        r = spec.rule(comparator="between", low=lo, high=hi, threshold_basis="rounded lower and upper quartiles of historical moves over the same distance")
        made.append(Call(
            id=_qid(made_on, spec, h, "range"), kind="binary", rule=r,
            question=f"Will {spec.noun} for {tp} be at least {spec.fmt(lo)} and below {spec.fmt(hi)}?",
            base_rate=hist.base_rate(r), **common,  # type: ignore[arg-type]
        ))
        # number
        made.append(Call(
            id=_qid(made_on, spec, h, "number"), kind="number", rule=spec.rule(),
            question=f"What will {spec.noun} be for {tp}?", **common,  # type: ignore[arg-type]
        ))
        # a yes/no question whose answer history never varies tells nothing: drop it
        out.extend(c for c in made if c.kind == "number" or (c.base_rate is not None and 0.0 < c.base_rate < 1.0))
    return out


def generate(
    series: dict[str, Series],
    made_on: date,
    split: str,
    specs: Iterable[Spec] = SPECS,
    horizons: Sequence[int] = HORIZONS,
    live_cutoff: bool = False,
) -> list[Call]:
    """Questions for every series on one date.

    ``live_cutoff=True`` uses the last reading actually present (what was really
    published by today) instead of the publication-lag rule; use it only for
    the live set, where the series copy was taken on ``made_on``.
    """
    out: list[Call] = []
    for spec in specs:
        s = series.get(spec.id)
        if s is None or not len(s):
            continue
        cutoff = None
        if live_cutoff:
            last = s.last_on_or_before(made_on)
            cutoff = last[0] if last else None
        out.extend(questions_for(spec, s, made_on, split, horizons, cutoff))
    return out


def info_for(spec: Spec, base: SeriesInfo | None = None) -> SeriesInfo:
    """Series metadata carrying the spec's cadence and publication lag."""
    b = base or SeriesInfo(id=spec.id)
    extra = dict(b.extra)
    extra["agency_series"] = spec.agency_series
    return replace(b, period=spec.period, publish_lag_days=spec.publish_lag_days, extra=extra)
